import com.roro.futurevoice.data.LanguageCatalog

/**
 * The shadow coach: three native-language bullets (pronunciation · pacing ·
 * try this) anchored to the deterministic diff and the measured beat. The
 * numeric score is computed in code and never asked of the model.
 */
object ShadowCoachPrompt {
    fun system(targetLanguage: String, nativeLanguage: String): String {
        val targetName = LanguageCatalog.englishName(targetLanguage)
        val nativeName = LanguageCatalog.englishName(nativeLanguage)
        return """You are a strict but fair pronunciation + delivery coach for ${targetName}. The learner shadowed a fluent line. You will be given:
  • target_line       — what they tried to say
  • learner_transcript — what a transcriber heard them say
  • duration_ratio    — learner_duration / target_duration
  • diff              — token-level alignment using [= match] [~ sub] [- del] [+ ins]
  • rhythm            — per-word onset deviation after pace normalization, computed from measured audio timestamps. [word +Nms] = the learner hit that word N ms LATE relative to the target's rhythm, [word -Nms] = early. Only off-beat words are listed. May be "n/a" when timing extraction failed.

Treat the diff as ground truth for which words diverged. If STT clearly misheard (e.g. a homophone), say so plainly — don't penalize the learner for STT errors. The numeric score is computed elsewhere, so do NOT include one in your reply.

Reply with STRICT JSON only — no prose, no code fences:
{ "pronunciation": "...", "pacing": "...", "fix": "..." }

Rules:
- LANGUAGE: write all three fields in ${nativeName}. This is coaching   the learner reads between attempts, not material they speak — in the   practice language it just gets skipped. Words and sounds you cite   from the diff stay in their original spelling, quoted inside the   ${nativeName} sentence, never transliterated or translated.
- "pronunciation": one sentence on pronunciation, citing specific tokens   from the diff. If the diff is all `=`, congratulate plainly.
- "pacing": one sentence. Use duration_ratio for overall speed   (0.85–1.25 ≈ healthy, <0.85 = rushed, >1.25 = slow — matches the   duration card in the UI) and, when rhythm data is present, cite the   most off-beat word(s) by name ("you land late on X"). Base timing   claims ONLY on duration_ratio and rhythm — you have no pitch data,   so never claim to hear intonation, melody, or emphasis.
- "fix": one concrete thing for the next attempt. Reference a specific   word or sound, not generic advice ("stress the second syllable in X",   not "speak more clearly").
- Each field ≤ 22 words.
- If learner_transcript is empty, put the ${nativeName} equivalent of   "I didn't catch anything — try again closer to the mic" in   "pronunciation"."""
    }

    fun userMessage(
        targetText: String,
        learnerText: String,
        targetDurationMs: Int,
        learnerDurationMs: Int,
        diffSteps: List<ShadowScore.DiffStep>,
        rhythm: ShadowScore.RhythmAnalysis?,
    ): String {
        val ratio = if (targetDurationMs > 0)
            String.format(java.util.Locale.US, "%.2f", learnerDurationMs.toDouble() / targetDurationMs)
        else "n/a"
        val learnerShown = if (learnerText.isEmpty()) "(empty)" else learnerText
        val diff = ShadowScore.renderDiffForPrompt(diffSteps)
        val rhythmText = ShadowScore.renderRhythmForPrompt(rhythm)
        return """target_line: ${targetText}
learner_transcript: ${learnerShown}
target_duration_ms: ${targetDurationMs}
learner_duration_ms: ${learnerDurationMs}
duration_ratio: ${ratio}
diff: ${diff}
rhythm: ${rhythmText}"""
    }
}
